# An MCP client, known by its Client ID Metadata Document (generated by
# maquina:oauth). The client_id is the https URL of that document; there is
# no registration endpoint and no client secret.
class OauthClient < ApplicationRecord
  METADATA_TTL = 24.hours

  has_many :oauth_authorization_codes, dependent: :destroy
  has_many :access_tokens, dependent: :destroy

  serialize :redirect_uris, coder: JSON

  validates :client_id, presence: true, uniqueness: true
  validates :client_name, :metadata_fetched_at, presence: true

  # The client for a client_id, fetched (MetadataFetcher) when it is new or
  # its stored copy is older than METADATA_TTL. Raises
  # MetadataFetcher::Refused when the document cannot be trusted.
  def self.from_metadata!(client_id)
    client = find_or_initialize_by(client_id: client_id)
    return client if client.persisted? && client.metadata_fresh?

    metadata = MetadataFetcher.fetch(client_id)
    client.update!(client_name: metadata["client_name"].strip.truncate(100),
      redirect_uris: metadata["redirect_uris"], metadata_fetched_at: Time.current)
    client
  rescue ActiveRecord::RecordNotUnique
    # Two first fetches of the same document raced and the other one stored
    # it first (caught by the unique index here, by the uniqueness check
    # below): its copy is just as fresh.
    find_by!(client_id: client_id)
  rescue ActiveRecord::RecordInvalid => error
    raise unless error.record.errors.of_kind?(:client_id, :taken)

    find_by!(client_id: client_id)
  end

  def metadata_fresh?
    metadata_fetched_at.present? && metadata_fetched_at > METADATA_TTL.ago
  end

  # Exact match only: no prefix, no port or path leniency.
  def redirect_uri?(uri)
    Array(redirect_uris).include?(uri)
  end

  # The domain shown on the consent screen, so people see who is really asking.
  def host
    URI(client_id).host
  end
end
